# Round 6: one standard red / yellow / green palette (status.css, generated by dev/tools/gen_status.py),
# colour-coded summary tiles on every page, numbers that always fit, no black fills, spacing,
# Orders and Messages visual revamp (r6.css, r6.js, r6_orders.css, r6_messages.css).
import os
from patchlib import P, S
HERE = os.path.dirname(__file__)
def rd(n):
    p = os.path.join(HERE, n)
    return open(p, encoding='utf-8').read() if os.path.exists(p) else ''
P("function renderSidebarForViewAsRole(){", rd('r6.js') + "\nfunction renderSidebarForViewAsRole(){")
t = S['text']; i = t.rindex('  .settings-card:empty{display:none;}')
S['text'] = t[:i] + rd('status.css') + '\n/* ===== Round 6 css begin ===== */\n' + rd('r6.css') + rd('r6_orders.css') + rd('r6_messages.css') + '\n/* ===== Round 6 css end ===== */\n' + t[i:]

# money: minus sign before the peso sign (−₱919, not ₱-919)
P("function fmtPHP(n){ return '₱' + roundPeso(n).toLocaleString('en-US'); }",
  "function fmtPHP(n){ const r = roundPeso(n); return (r < 0 ? '−₱' : '₱') + Math.abs(r).toLocaleString('en-US'); }")
# Orders tables (both sides): status chips carry their own colour; rows that need you get a yellow edge;
# promised date reads like a person would say it; a real View button
P("""const b = (k, label, cnt) => `<button class="${seg === k ? 'on' : ''} ${k === 'turn' && cnt ? 'turn' : ''}" onclick=""",
  """const b = (k, label, cnt) => `<button class="seg-${k} ${seg === k ? 'on' : ''} ${k === 'turn' && cnt ? 'turn' : ''}" onclick=""")
P("""<td class="po-cell" style="${needsAction ? `border-left:6px solid var(--lowstock-fill);` : ''}">""", """<td class="po-cell">""", 2)
P("""<tr style="cursor:pointer;" onclick="toggleSupplierOrder('${o.id}')" class="${selected ? 'order-row-selected' : ''}">""",
  """<tr style="cursor:pointer;" onclick="toggleSupplierOrder('${o.id}')" class="${selected ? 'order-row-selected' : ''}${needsAction ? ' ord-turn' : ''}">""")
P("""<tr onclick="toggleOrderRow('${o.id}')" style="cursor:pointer;" class="${selected ? 'order-row-selected' : ''}">""",
  """<tr onclick="toggleOrderRow('${o.id}')" style="cursor:pointer;" class="${selected ? 'order-row-selected' : ''}${needsAction ? ' ord-turn' : ''}">""")
P("""<div style="font-size:12.5px;color:var(--ink);opacity:.6;font-weight:600;margin-top:1px;">${statusCaption}</div>""",
  """<div class="ord-st${/late/.test(statusCaption) ? ' late' : /on time/.test(statusCaption) ? ' ok' : ''}">${statusCaption}</div>""")
P("""<div style="font-size:12.5px;color:var(--ink);opacity:.6;font-weight:600;margin-top:1px;">${PO_STATUS_LABELS[o.status]}</div>""",
  """<div class="ord-st">${PO_STATUS_LABELS[o.status]}</div>""")
P("""<span style="color:var(--ink);font-size:15px;">×${o.lineItems[0].qty}</span></td>
      <td>${o.requestedDeliveryDate}</td>""",
  """<span class="ord-qty">×${o.lineItems[0].qty}</span></td>
      <td class="ord-due">${nfDue(o)}</td>""")
P("""<td><span class="row-action">${selected ? 'Close ▲' : 'View ▼'}</span></td>""",
  """<td class="ord-v"><span class="row-action ord-view${selected ? ' open' : ''}">${selected ? 'Close' : 'View'}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></span></td>""")
P("""<td><span class="row-action">${open ? 'Close ▲' : 'View ▼'}</span></td>""",
  """<td><span class="row-action ord-view${open ? ' open' : ''}">${open ? 'Close' : 'View'}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></span></td>""")

# order detail: red alert box for at-risk orders, friendly delivery date, tidy "not in your catalog" note
P("""${o.riskNote ? `<div class="logi-note" style="color:var(--danger);">⏱ ${o.riskNote}</div>` : ''}""",
  """${o.riskNote ? `<div class="logi-note od-risk">⏱ ${o.riskNote}</div>` : ''}""", 2)
P("""<strong>Requested delivery:</strong> ${o.requestedDeliveryDate || "not set"} · <strong>Ship to:</strong>""",
  """<strong>Requested delivery:</strong> ${o.requestedDeliveryDate ? stmtDate(o.requestedDeliveryDate) : "not set"} · <strong>Ship to:</strong>""", 2)
P("""const newBadge = isNew ? `<span style="color:var(--lowstock);font-weight:700;font-size:15px;">🆕 Not in your catalog yet</span>` : '';
      const newActions = isNew ? ` · <span class="row-action" onclick="event.stopPropagation(); openEditLineItemNameForm('${o.id}', ${i})">Edit name</span> · <span class="row-action" onclick="event.stopPropagation(); addNewLineItemToMyCatalog('${o.id}', ${i})">+ Add to my catalog</span>` : '';
      return `<div style="font-size:15px;color:var(--ink);display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;padding:4px 0;">
      <span>${li.product} ${newBadge}</span>
      <span>${newActions} ${newActions?' · ':''}<span class="row-action" onclick="event.stopPropagation(); openDiscontinuedForm('${o.id}', ${i})">Mark Discontinued + Suggest Replacement</span></span>
    </div>""",
  """const newBadge = isNew ? `<span class="od-new">🆕 Not in your catalog yet</span>` : '';
      const newActions = isNew ? `<span class="row-action" onclick="event.stopPropagation(); openEditLineItemNameForm('${o.id}', ${i})">Edit name</span><span class="row-action" onclick="event.stopPropagation(); addNewLineItemToMyCatalog('${o.id}', ${i})">+ Add to my catalog</span>` : '';
      return `<div class="od-li${isNew ? ' new' : ''}">
      <span class="od-li-n"><b>${li.product}</b> ${newBadge}</span>
      <span class="od-li-a">${newActions}<span class="row-action" onclick="event.stopPropagation(); openDiscontinuedForm('${o.id}', ${i})">Mark Discontinued + Suggest Replacement</span></span>
    </div>""")
